#!/usr/bin/env python3
"""Commit src/components/Header.tsx — agregar tab ISO 226"""
import subprocess, base64, os, sys

os.chdir(os.path.expanduser("~/IVANNA-OMEGA-SUPREME"))

r = subprocess.run(["git","pull","--rebase","origin","main"], capture_output=True, text=True)
print(r.stdout.strip())
if r.returncode != 0:
    print("ERROR pull:", r.stderr); sys.exit(1)

data = base64.b64decode("""""")
target = "src/components/Header.tsx"
with open(target, "wb") as f:
    f.write(data)
print(f"✅ Escrito: {target} ({len(data)} bytes)")

r = subprocess.run(["git","add", target], capture_output=True, text=True)
if r.returncode != 0:
    print("ERROR add:", r.stderr); sys.exit(1)

r = subprocess.run(["git","status","--porcelain", target], capture_output=True, text=True)
if not r.stdout.strip():
    print("ℹ️  Sin cambios (ya commitado)"); sys.exit(0)
print("Staged:", r.stdout.strip())

r = subprocess.run(["git","commit","-m","feat(header): agregar tab ISO 226 Calibr. con icono BarChart2 + tipos actualizados"], capture_output=True, text=True)
print(r.stdout.strip())
if r.returncode != 0:
    print("ERROR commit:", r.stderr); sys.exit(1)

r = subprocess.run(["git","push","origin","main"], capture_output=True, text=True)
print(r.stdout.strip(), r.stderr.strip())
if r.returncode != 0:
    print("ERROR push:", r.stderr); sys.exit(1)
print("✅ Header.tsx pushed")
